 dict(kind="list", icon="📏", head="भूमि सुधार के और क़दम",
      points=["हदबंदी (सीलिंग) क़ानून: एक परिवार एक सीमा से ज़्यादा ज़मीन नहीं रख सकता", "फ़ालतू ज़मीन भूमिहीनों में बाँटना", "भूदान आंदोलन (1951): विनोबा भावे — 'ज़मीन दान दो' · बिहार में सबसे ज़्यादा भूदान", "चकबंदी: बिखरे खेतों को मिलाकर एक जगह · बटाईदारों के हक़"],
      say="भूमि सुधार के और क़दम उठे। हदबंदी क़ानून, जिससे तय हुआ कि एक परिवार एक सीमा से ज़्यादा ज़मीन नहीं रख सकता, और फ़ालतू ज़मीन भूमिहीनों में बाँटी जाएगी। उन्नीस सौ इक्यावन में, आचार्य विनोबा भावे ने भूदान आंदोलन शुरू किया, वो गाँव-गाँव पैदल घूमकर ज़मींदारों से कहते, अपनी ज़मीन का एक हिस्सा भूमिहीन भाइयों को दान दो। बिहार में सबसे ज़्यादा ज़मीन दान में मिली। और चकबंदी, यानी किसान के बिखरे हुए छोटे खेतों को मिलाकर, एक जगह करना। हालाँकि ये सुधार पूरी तरह लागू नहीं हो पाए, और आज भी बहुत से लोग भूमिहीन हैं।"),

 dict(kind="content", icon="🌱", head="हरित क्रांति (1960 के दशक)",
      points=["1960 के दशक: अनाज की कमी, विदेश से गेहूँ मँगाना पड़ता", "नॉर्मन बोरलॉग (मेक्सिको के बौने गेहूँ) + एम.एस. स्वामीनाथन (भारत में हरित क्रांति के जनक)", "HYV (अधिक उपज वाले) बीज + रासायनिक खाद + सिंचाई + कीटनाशक", "पंजाब, हरियाणा, पश्चिमी यूपी में गेहूँ की बंपर पैदावार · देश अनाज में आत्मनिर्भर"],
      say="उन्नीस सौ साठ के दशक में, देश में अनाज की भारी कमी थी, अमेरिका से गेहूँ मँगाना पड़ता था। तब आई हरित क्रांति। अमेरिकी वैज्ञानिक नॉर्मन बोरलॉग ने मेक्सिको में गेहूँ की बौनी, ज़्यादा उपज वाली किस्में बनाई थीं। भारत के कृषि वैज्ञानिक एम एस स्वामीनाथन, जिन्हें भारत में हरित क्रांति का जनक कहते हैं, ने इन्हें यहाँ के हिसाब से ढाला। ज़्यादा उपज वाले बीज, रासायनिक खाद, सिंचाई और कीटनाशक, इन चारों के मेल से, पंजाब, हरियाणा और पश्चिमी उत्तर प्रदेश में गेहूँ की बंपर पैदावार हुई। कुछ ही सालों में देश अनाज में आत्मनिर्भर हो गया।"),

